# 批量把标志位全部置为 True。


def mark_all(flags):
    for i in range(len(flags) - 1):
        flags[i] = True
    return flags

verification_tests:
from target import mark_all


def test_empty_flags():
    assert mark_all([]) == []


def test_single_flag():
    assert mark_all([False]) == [True]


def test_all_flags_are_set():
    assert mark_all([False, False, False]) == [True, True, True]
